import { useEffect, useRef, useState, useCallback } from 'react';

/* =========================================================================
   JointSaathi — Interactive 3D exploded view of the knee wearable
   -------------------------------------------------------------------------
   - Three.js is loaded at runtime from cdnjs (no bundler dependency, no
     external model files — every part is procedural geometry built here).
   - Fully self-contained: styles are injected once via a <style> tag with
     an id guard, so this file can be dropped into any React project.
   - Reads the page's own CSS custom properties (--primary, --text-*, etc.)
     with safe fallbacks, so the chrome (labels, lines, button) matches
     whatever page it's dropped into without edits.
   ========================================================================= */

/* ---------- small math helpers ---------- */
const clamp = (v, min, max) => Math.min(max, Math.max(min, v));
const lerp = (a, b, t) => a + (b - a) * t;
const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
const smoothstep = (edge0, edge1, x) => {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
};
const degToRad = (d) => (d * Math.PI) / 180;

/* ---------- theme resolution: read the page's own CSS vars ---------- */
function readTheme() {
  const root =
    typeof document !== 'undefined' ? getComputedStyle(document.documentElement) : null;
  const pick = (name, fallback) => {
    const v = root ? root.getPropertyValue(name).trim() : '';
    return v || fallback;
  };
  return {
    primary: pick('--primary', '#6B8A72'),
    primaryDark: pick('--primary-dark', '#34483D'),
    primaryLight: pick('--primary-light', '#8CAE92'),
    primarySurface: pick('--primary-surface', '#EAF0E7'),
    accent: pick('--accent', '#D3A0A0'),
    textPrimary: pick('--text-primary', '#2F302E'),
    textSecondary: pick('--text-secondary', '#5B5E58'),
    textTertiary: pick('--text-tertiary', '#8A8D86'),
    border: pick('--border', '#E5E2DB'),
    background: pick('--background', '#FBFAF6'),
    fontDisplay: pick('--font-display', 'inherit'),
    fontBody: pick('--font-body', 'inherit'),
  };
}

/* ---------- three.js CDN loader (memoised across mounts) ---------- */
const THREE_CDN_URLS = [
  'https://cdnjs.cloudflare.com/ajax/libs/three.js/128/three.min.js',
  'https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js',
  'https://cdnjs.cloudflare.com/ajax/libs/three.js/0.128.0/three.min.js',
];

let threeLoadPromise = null;
function loadThree() {
  if (typeof window === 'undefined') return Promise.reject(new Error('no window'));
  if (window.THREE) return Promise.resolve(window.THREE);
  if (threeLoadPromise) return threeLoadPromise;

  threeLoadPromise = new Promise((resolve, reject) => {
    let i = 0;
    const tryNext = () => {
      if (window.THREE) {
        resolve(window.THREE);
        return;
      }
      if (i >= THREE_CDN_URLS.length) {
        reject(new Error('Could not load three.js from cdnjs'));
        return;
      }
      const url = THREE_CDN_URLS[i++];
      const script = document.createElement('script');
      script.src = url;
      script.async = true;
      script.crossOrigin = 'anonymous';
      const timeout = setTimeout(() => {
        script.onerror = script.onload = null;
        tryNext();
      }, 7000);
      script.onload = () => {
        clearTimeout(timeout);
        if (window.THREE) resolve(window.THREE);
        else tryNext();
      };
      script.onerror = () => {
        clearTimeout(timeout);
        tryNext();
      };
      document.head.appendChild(script);
    };
    tryNext();
  });

  return threeLoadPromise;
}

function webglAvailable() {
  try {
    const canvas = document.createElement('canvas');
    return !!(
      window.WebGLRenderingContext &&
      (canvas.getContext('webgl') || canvas.getContext('experimental-webgl'))
    );
  } catch (e) {
    return false;
  }
}

/* =========================================================================
   PROCEDURAL GEOMETRY BUILDERS
   Every function takes THREE and returns a THREE.Group centred on its own
   local origin. Materials are created fresh per call (no shared state)
   so each instance can be dimmed/highlighted independently.
   ========================================================================= */

function makeMat(THREE, opts) {
  return new THREE.MeshStandardMaterial({
    transparent: true,
    opacity: 1,
    ...opts,
  });
}

/* ---------- real sensor photos (embedded so this file stays self-contained) ---------- */
const SENSOR_IMG = {
  mpu6050: 'data:image/jpeg;base64,',
  emg: 'data:image/jpeg;base64,',
  esp32: 'data:image/jpeg;base64,',
};

function makeImageMat(THREE, src, { rotation = 0 } = {}) {
  const tex = new THREE.TextureLoader().load(src);
  if (THREE.sRGBEncoding !== undefined) tex.encoding = THREE.sRGBEncoding;
  tex.anisotropy = 4;
  if (rotation) {
    tex.center.set(0.5, 0.5);
    tex.rotation = rotation;
  }
  return makeMat(THREE, { map: tex, roughness: 0.55, metalness: 0.05 });
}

/* thin ridge lines around a cylindrical or box holder to suggest visible
   FDM layer lines, without needing an external texture */
function addLayerLines(THREE, group, { radius, height, segments = 10, color = 0xd8d2c2, box = null }) {
  const lineMat = makeMat(THREE, { color, roughness: 0.7, metalness: 0.02 });
  if (box) {
    const [w, h, d] = box;
    const n = 5;
    for (let i = 1; i < n; i++) {
      const y = -h / 2 + (h / n) * i;
      const geo = new THREE.BoxGeometry(w * 1.002, h / (n * 6), d * 1.002);
      const m = new THREE.Mesh(geo, lineMat);
      m.position.y = y;
      group.add(m);
    }
  } else {
    for (let i = 1; i < segments; i++) {
      const y = -height / 2 + (height / segments) * i;
      const geo = new THREE.TorusGeometry(radius * 1.01, height / (segments * 9), 6, 20);
      const m = new THREE.Mesh(geo, lineMat);
      m.rotation.x = Math.PI / 2;
      m.position.y = y;
      group.add(m);
    }
  }
}

function buildLeg(THREE, theme) {
  const group = new THREE.Group();
  const mat = makeMat(THREE, {
    color: 0xcdd6d9,
    roughness: 1,
    metalness: 0,
    opacity: 0.16,
    depthWrite: false,
  });

  const thigh = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.58, 1.7, 28, 1, true), mat);
  thigh.position.y = 0.95;
  group.add(thigh);

  const shin = new THREE.Mesh(new THREE.CylinderGeometry(0.56, 0.4, 1.7, 28, 1, true), mat);
  shin.position.y = -0.95;
  group.add(shin);

  const kneeBulge = new THREE.Mesh(new THREE.SphereGeometry(0.6, 28, 20), mat);
  kneeBulge.scale.set(1, 0.62, 1);
  group.add(kneeBulge);

  group.renderOrder = -1;
  group.traverse((o) => {
    if (o.isMesh) o.renderOrder = -1;
  });
  return group;
}

function buildShadowCatcher(THREE) {
  const geo = new THREE.PlaneGeometry(14, 14);
  const mat = new THREE.ShadowMaterial({ opacity: 0.16 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = -1.98;
  mesh.receiveShadow = true;
  return mesh;
}

function buildStrap(THREE) {
  const group = new THREE.Group();
  const fabric = makeMat(THREE, { color: 0x2a2e2c, roughness: 0.95, metalness: 0.02 });
  const fabricAlt = makeMat(THREE, { color: 0x3a3f3c, roughness: 0.92, metalness: 0.02 });

  // main wrap — an arc torus leaving a small gap for the velcro overlap
  const band = new THREE.Mesh(
    new THREE.TorusGeometry(0.62, 0.11, 14, 48, Math.PI * 1.82),
    fabric
  );
  band.rotation.x = Math.PI / 2;
  band.rotation.z = Math.PI * 0.44;
  band.castShadow = true;
  group.add(band);

  // velcro overlap tab bridging the gap
  const tab = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.2, 0.05), fabricAlt);
  tab.position.set(0.58, 0, 0.34);
  tab.rotation.y = degToRad(-28);
  tab.castShadow = true;
  group.add(tab);

  const stitchMat = makeMat(THREE, { color: 0x55584f, roughness: 0.8, metalness: 0.05 });
  const stitch = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.012, 6, 48, Math.PI * 1.82), stitchMat);
  stitch.rotation.copy(band.rotation);
  stitch.position.y = 0.085;
  group.add(stitch);

  return group;
}

function buildHolderShell(THREE, { w = 0.34, h = 0.22, d = 0.28 } = {}) {
  const group = new THREE.Group();
  const plastic = makeMat(THREE, { color: 0xece6d8, roughness: 0.55, metalness: 0.04 });
  const shell = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), plastic);
  shell.castShadow = true;
  shell.receiveShadow = true;
  group.add(shell);
  addLayerLines(THREE, group, { box: [w, h, d] });
  return group;
}

function buildImuAssembly(THREE) {
  const group = new THREE.Group();

  // real MPU6050 photo on a thin board, facing outward from the knee
  const w = 0.3;
  const h = 0.386;
  const t = 0.02;
  const bodyMat = makeMat(THREE, { color: 0x1d3fa0, roughness: 0.6, metalness: 0.1 });
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, t), bodyMat);
  body.castShadow = true;
  group.add(body);

  const face = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    makeImageMat(THREE, SENSOR_IMG.mpu6050)
  );
  face.position.z = t / 2 + 0.001;
  group.add(face);

  return group;
}

function buildEmgAssembly(THREE) {
  const group = new THREE.Group();

  // real EMG sensor module photo on a thin red board, facing outward
  const w = 0.34;
  const h = 0.39;
  const t = 0.02;
  const bodyMat = makeMat(THREE, { color: 0xb3161d, roughness: 0.6, metalness: 0.1 });
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, t), bodyMat);
  body.castShadow = true;
  group.add(body);

  const face = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    makeImageMat(THREE, SENSOR_IMG.emg)
  );
  face.position.z = t / 2 + 0.001;
  group.add(face);

  return group;
}

function buildPiezoAssembly(THREE) {
  const group = new THREE.Group();
  const holder = new THREE.Group();
  const plastic = makeMat(THREE, { color: 0xece6d8, roughness: 0.55, metalness: 0.04 });
  const tray = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 0.09, 24), plastic);
  tray.castShadow = true;
  tray.receiveShadow = true;
  holder.add(tray);
  addLayerLines(THREE, holder, { radius: 0.2, height: 0.09, segments: 4 });
  group.add(holder);

  const brassMat = makeMat(THREE, { color: 0xc9a227, roughness: 0.3, metalness: 0.85 });
  const ring = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 0.03, 28), brassMat);
  ring.position.y = 0.06;
  ring.castShadow = true;
  group.add(ring);

  const blackMat = makeMat(THREE, { color: 0x121316, roughness: 0.5, metalness: 0.2 });
  const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.018, 28), blackMat);
  disc.position.y = 0.078;
  group.add(disc);

  return group;
}

function buildElectrode(THREE) {
  const group = new THREE.Group();
  const base = makeMat(THREE, { color: 0x232624, roughness: 0.6, metalness: 0.08 });
  const mount = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.11, 0.03, 20), base);
  mount.castShadow = true;
  group.add(mount);

  const snapMat = makeMat(THREE, { color: 0xc6cbcb, roughness: 0.25, metalness: 0.85 });
  const snap = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.06, 0.03, 18), snapMat);
  snap.position.y = 0.03;
  snap.castShadow = true;
  group.add(snap);

  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.025, 12, 10), snapMat);
  dot.position.y = 0.06;
  group.add(dot);

  return group;
}

function buildWireBetween(THREE, from, to, color = 0x1c1c1c, radius = 0.012) {
  const mid = new THREE.Vector3(
    (from.x + to.x) / 2 + (Math.random() - 0.5) * 0.05,
    (from.y + to.y) / 2 + 0.06,
    (from.z + to.z) / 2 + (Math.random() - 0.5) * 0.05
  );
  const curve = new THREE.QuadraticBezierCurve3(from, mid, to);
  const geo = new THREE.TubeGeometry(curve, 16, radius, 6, false);
  const mat = makeMat(THREE, { color, roughness: 0.75, metalness: 0.05 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.castShadow = true;
  return mesh;
}

function buildOnboardElectronics(THREE) {
  const group = new THREE.Group();

  // ESP32 dev board (real photo on top of the board)
  const espMat = makeMat(THREE, { color: 0x111214, roughness: 0.6, metalness: 0.12 });
  const esp = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.03, 0.24), espMat);
  esp.position.set(-0.18, 0, 0);
  esp.castShadow = true;
  group.add(esp);

  const espFace = new THREE.Mesh(
    new THREE.PlaneGeometry(0.46, 0.24),
    makeImageMat(THREE, SENSOR_IMG.esp32, { rotation: -Math.PI / 2 })
  );
  espFace.rotation.x = -Math.PI / 2;
  espFace.position.set(-0.18, 0.0155, 0);
  group.add(espFace);

  // Li-ion battery pouch
  const battMat = makeMat(THREE, { color: 0xc9cdd3, roughness: 0.35, metalness: 0.55 });
  const battery = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.06, 0.22), battMat);
  battery.position.set(0.26, 0, -0.02);
  battery.castShadow = true;
  group.add(battery);
  const battLabel = makeMat(THREE, { color: 0x6b8a72, roughness: 0.6, metalness: 0.05 });
  const label = new THREE.Mesh(new THREE.PlaneGeometry(0.18, 0.1), battLabel);
  label.rotation.x = -Math.PI / 2;
  label.position.set(0.26, 0.031, -0.02);
  group.add(label);

  // microSD module
  const sdMat = makeMat(THREE, { color: 0x111214, roughness: 0.45, metalness: 0.3 });
  const sd = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.015, 0.07), sdMat);
  sd.position.set(0.04, 0.03, 0.2);
  sd.castShadow = true;
  group.add(sd);
  const goldMat = makeMat(THREE, { color: 0xd4af61, roughness: 0.3, metalness: 0.8 });
  const contacts = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.006, 0.02), goldMat);
  contacts.position.set(0.04, 0.039, 0.17);
  group.add(contacts);

  // wiring between the pieces
  group.add(buildWireBetween(THREE, new THREE.Vector3(-0.18, 0.02, 0.08), new THREE.Vector3(0.14, 0.02, -0.02)));
  group.add(buildWireBetween(THREE, new THREE.Vector3(-0.18, 0.02, -0.08), new THREE.Vector3(0.02, 0.03, 0.17)));

  group.rotation.x = Math.PI / 2; // face outward so the board photo is visible
  return group;
}

function buildPouch(THREE) {
  const group = new THREE.Group();
  const fabric = makeMat(THREE, { color: 0x242725, roughness: 0.93, metalness: 0.02 });
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.34, 0.4), fabric);
  body.castShadow = true;
  body.receiveShadow = true;
  group.add(body);

  const flapMat = makeMat(THREE, { color: 0x34382f, roughness: 0.9, metalness: 0.02 });
  const flap = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.1, 0.42), flapMat);
  flap.position.set(0, 0.18, -0.02);
  flap.rotation.x = degToRad(-8);
  flap.castShadow = true;
  group.add(flap);

  const portMat = makeMat(THREE, { color: 0x0b0c0d, roughness: 0.5, metalness: 0.15 });
  const port = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.05, 0.1), portMat);
  port.position.set(0.31, -0.02, 0);
  group.add(port);

  const stitchMat = makeMat(THREE, { color: 0x4d5148, roughness: 0.8, metalness: 0.05 });
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.BoxGeometry(0.62, 0.34, 0.4)),
    new THREE.LineBasicMaterial({ color: 0x4d5148, transparent: true, opacity: 0.5 })
  );
  group.add(edges);

  return group;
}

/* =========================================================================
   PART CONFIGURATION — positions, explode direction/distance, stagger
   ========================================================================= */

function dirFromAngle(deg, yBias = 0) {
  const rad = degToRad(deg);
  return { x: Math.sin(rad), y: yBias, z: Math.cos(rad) };
}

function polar(deg, radius, y) {
  const rad = degToRad(deg);
  return { x: Math.sin(rad) * radius, y, z: Math.cos(rad) * radius };
}

