/* =========================================================================
   REACT COMPONENT
   ========================================================================= */

const STYLE_TAG_ID = 'kx-explode-styles';
function injectStyles() {
  if (typeof document === 'undefined' || document.getElementById(STYLE_TAG_ID)) return;
  const style = document.createElement('style');
  style.id = STYLE_TAG_ID;
  style.textContent = `
  .kx-section { position: relative; }
  .kx-stage-spacer { position: relative; height: 230vh; }
  .kx-stage-sticky {
    position: sticky;
    top: 84px;
    height: min(78vh, 640px);
    border-radius: 22px;
    overflow: hidden;
    background:
      radial-gradient(circle at 80% 15%, rgba(211,160,160,.14), transparent 50%),
      radial-gradient(circle at 10% 90%, rgba(140,174,146,.16), transparent 55%),
      linear-gradient(160deg, #1c2721, var(--kx-primary-dark, #34483D) 120%);
    border: 1px solid rgba(255,255,255,0.1);
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.06), 0 40px 80px -40px rgba(10,16,12,0.55);
  }
  .kx-canvas-host { position: absolute; inset: 0; cursor: grab; touch-action: pan-y; }
  .kx-canvas-host.kx-dragging { cursor: grabbing; }
  .kx-canvas-host canvas { display: block; width: 100%; height: 100%; }
  .kx-overlay-svg { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
  .kx-labels { position: absolute; inset: 0; pointer-events: none; }
  .kx-label {
    position: absolute;
    transform: translate(-50%, -50%);
    display: inline-flex;
    flex-direction: column;
    gap: 2px;
    padding: 7px 11px;
    border-radius: 10px;
    background: rgba(18,24,20,0.78);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    border: 1px solid rgba(255,255,255,0.14);
    box-shadow: 0 10px 24px -14px rgba(0,0,0,0.55);
    font-family: var(--kx-font-body, inherit);
    max-width: 200px;
    opacity: 0;
    transition: box-shadow .18s ease, border-color .18s ease;
    white-space: normal;
  }
  .kx-label.kx-hovered { box-shadow: 0 12px 28px -10px rgba(0,0,0,0.6); border-color: var(--kx-primary-light, #8CAE92); }
  .kx-label strong { font-size: 12px; font-weight: 700; color: #F4F2EC; line-height: 1.25; }
  .kx-label span { font-size: 10.5px; line-height: 1.4; color: rgba(244,242,236,0.62); }
  .kx-toolbar {
    position: absolute;
    top: 14px;
    right: 14px;
    z-index: 5;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .kx-toggle {
    border: 1px solid rgba(255,255,255,0.16);
    cursor: pointer;
    font-family: var(--kx-font-body, inherit);
    font-size: 13px;
    font-weight: 600;
    padding: 9px 16px;
    border-radius: 999px;
    background: var(--kx-primary, #6B8A72);
    color: #fff;
    box-shadow: 0 10px 24px -12px rgba(0,0,0,0.5);
  }
  .kx-toggle:hover { filter: brightness(1.08); }
  .kx-toggle:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
  .kx-hint {
    position: absolute;
    left: 14px;
    bottom: 12px;
    font-size: 11px;
    color: rgba(244,242,236,0.65);
    font-family: var(--kx-font-body, inherit);
    background: rgba(18,24,20,0.55);
    padding: 5px 10px;
    border-radius: 999px;
    pointer-events: none;
  }
  .kx-loading {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    color: rgba(244,242,236,0.65);
    font-family: var(--kx-font-body, inherit);
  }
  .kx-sr-only {
    position: absolute;
    width: 1px; height: 1px;
    padding: 0; margin: -1px;
    overflow: hidden;
    clip: rect(0,0,0,0);
    white-space: nowrap;
    border: 0;
  }
  .kx-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
  }
  .kx-fallback svg { max-width: 100%; max-height: 100%; }
  @media (max-width: 760px) {
    .kx-stage-sticky { top: 64px; height: min(70vh, 520px); border-radius: 14px; }
    .kx-label { max-width: 150px; padding: 6px 9px; }
    .kx-label strong { font-size: 11px; }
    .kx-label span { font-size: 9.5px; }
  }
  `;
  document.head.appendChild(style);
}

export default function KneeDeviceExplodedView() {
  const sectionRef = useRef(null);
  const spacerRef = useRef(null);
  const canvasHostRef = useRef(null);
  const svgRef = useRef(null);
  const labelsHostRef = useRef(null);

  const [ready, setReady] = useState(false);
  const [webglError, setWebglError] = useState(false);
  const [exploded, setExploded] = useState(false);

  const modeRef = useRef('scroll'); // 'scroll' | 'manual'
  const manualTargetRef = useRef(0);
  const progressRef = useRef(0);
  const reducedMotionRef = useRef(false);

  const handleToggle = useCallback(() => {
    modeRef.current = 'manual';
    manualTargetRef.current = exploded ? 0 : 1;
    setExploded((v) => !v);
  }, [exploded]);

  useEffect(() => {
    injectStyles();

    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    reducedMotionRef.current = mq.matches;
    const onMq = (e) => {
      reducedMotionRef.current = e.matches;
    };
    mq.addEventListener ? mq.addEventListener('change', onMq) : mq.addListener(onMq);

    if (!webglAvailable()) {
      setWebglError(true);
      return () => {
        mq.removeEventListener ? mq.removeEventListener('change', onMq) : mq.removeListener(onMq);
      };
    }

    let disposed = false;
    let cleanupScene = null;

    loadThree()
      .then((THREE) => {
        if (disposed) return;
        try {
          cleanupScene = setupScene({
            THREE,
            canvasHost: canvasHostRef.current,
            svg: svgRef.current,
            labelsHost: labelsHostRef.current,
            spacer: spacerRef.current,
            section: sectionRef.current,
            modeRef,
            manualTargetRef,
            progressRef,
            reducedMotionRef,
          });
          setReady(true);
        } catch (err) {
          console.error('JointSaathi 3D view failed to initialise:', err);
          setWebglError(true);
        }
      })
      .catch((err) => {
        console.error('JointSaathi 3D view: three.js failed to load:', err);
        if (!disposed) setWebglError(true);
      });

    return () => {
      disposed = true;
      mq.removeEventListener ? mq.removeEventListener('change', onMq) : mq.removeListener(onMq);
      if (cleanupScene) cleanupScene();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const partDefs = buildPartDefs();

  return (
    <section id="device" className="landing__section landing__section--device kx-section" ref={sectionRef}>
      <div className="section-intro">
        <span className="section-kicker section-kicker--light">INSIDE THE DEVICE</span>
        <h2>One strap, five sensing parts, built to come apart.</h2>
        <p>
          Every piece of JointSaathi is modular and removable. Scroll through the device
          below, or use the toggle to pull it apart at your own pace.
        </p>
      </div>

      <div className="kx-stage-spacer" ref={spacerRef}>
        <div className="kx-stage-sticky">
          {!webglError && (
            <>
              <div className="kx-canvas-host" ref={canvasHostRef} aria-hidden="true" />
              <svg className="kx-overlay-svg" ref={svgRef} aria-hidden="true" />
              <div className="kx-labels" ref={labelsHostRef} aria-hidden="true" />
              {!ready && <div className="kx-loading">Loading 3D view…</div>}
              <div className="kx-toolbar">
                <button type="button" className="kx-toggle" onClick={handleToggle}>
                  {exploded ? 'Reassemble' : 'Explode view'}
                </button>
              </div>
              <span className="kx-hint">Drag to orbit · scroll to explode</span>
            </>
          )}

          {webglError && <StaticFallback partDefs={partDefs} />}

          {/* Accessible text description of every part, always present */}
          <ul className="kx-sr-only">
            {partDefs.map((p) => (
              <li key={p.id}>
                {p.label}: {p.desc}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </section>
  );
}

/* =========================================================================
   Static SVG fallback (no WebGL / three.js unavailable)
   ========================================================================= */
function StaticFallback({ partDefs }) {
  const positions = {
    'onboard-electronics': [560, 90],
    'electronics-pouch': [560, 170],
    'imu-sensor': [110, 70],
    'piezo-sensor': [90, 220],
    'emg-sensor': [560, 260],
    'emg-positive': [90, 300],
    'emg-negative': [110, 350],
    'emg-reference': [130, 400],
    'main-strap': [330, 430],
  };
  const cx = 330;
  const cy = 240;
  return (
    <div className="kx-fallback">
      <svg viewBox="0 0 660 470" width="660" height="470" role="img" aria-label="Exploded diagram of the JointSaathi knee wearable">
        <ellipse cx={cx} cy={cy} rx="70" ry="150" fill="#F4F2EC" opacity="0.14" />
        {partDefs.map((p) => {
          const [x, y] = positions[p.id] || [cx, cy];
          return (
            <g key={p.id}>
              <line x1={cx} y1={cy} x2={x} y2={y} stroke="rgba(244,242,236,0.4)" strokeWidth="1" />
              <circle cx={x} cy={y} r="7" fill="#8CAE92" />
              <text x={x + (x < cx ? -12 : 12)} y={y - 10} fontSize="12" fontWeight="700" fill="#F4F2EC" textAnchor={x < cx ? 'end' : 'start'}>
                {p.label}
              </text>
              <text x={x + (x < cx ? -12 : 12)} y={y + 6} fontSize="10" fill="rgba(244,242,236,0.65)" textAnchor={x < cx ? 'end' : 'start'}>
                <tspan x={x + (x < cx ? -12 : 12)}>{wrapText(p.desc, 34)[0]}</tspan>
                {wrapText(p.desc, 34)[1] && (
                  <tspan x={x + (x < cx ? -12 : 12)} dy="12">
                    {wrapText(p.desc, 34)[1]}
                  </tspan>
                )}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

function wrapText(text, maxLen) {
  if (text.length <= maxLen) return [text, ''];
  let cut = text.lastIndexOf(' ', maxLen);
  if (cut === -1) cut = maxLen;
  return [text.slice(0, cut), text.slice(cut + 1)];
}

/* =========================================================================
   THREE.JS SCENE SETUP — returns a cleanup function
   ========================================================================= */
function setupScene({
  THREE,
  canvasHost,
  svg,
  labelsHost,
  spacer,
  section,
  modeRef,
  manualTargetRef,
  progressRef,
  reducedMotionRef,
}) {
  const theme = readTheme();

  // push theme colours into CSS vars scoped to this section's chrome
  if (section) {
    section.style.setProperty('--kx-primary', theme.primary);
    section.style.setProperty('--kx-primary-dark', theme.primaryDark);
    section.style.setProperty('--kx-primary-surface', theme.primarySurface);
    section.style.setProperty('--kx-border', theme.border);
    section.style.setProperty('--kx-bg', theme.background);
    section.style.setProperty('--kx-text-primary', theme.textPrimary);
    section.style.setProperty('--kx-text-tertiary', theme.textTertiary);
    section.style.setProperty('--kx-font-body', theme.fontBody);
  }

  const partDefs = buildPartDefs();

  const scene = new THREE.Scene();

  const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 100);
  camera.position.set(0, 0.25, 7.4);
  camera.lookAt(0, 0, 0);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
  renderer.setClearColor(0x000000, 0);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  if (THREE.sRGBEncoding !== undefined) renderer.outputEncoding = THREE.sRGBEncoding;
  canvasHost.appendChild(renderer.domElement);

  // lights
  const hemi = new THREE.HemisphereLight(0xffffff, 0xd8d3c4, 0.95);
  scene.add(hemi);
  const key = new THREE.DirectionalLight(0xffffff, 1.15);
  key.position.set(3.2, 5, 4);
  key.castShadow = true;
  key.shadow.mapSize.set(1024, 1024);
  key.shadow.camera.near = 1;
  key.shadow.camera.far = 15;
  scene.add(key);
  const fill = new THREE.DirectionalLight(0xffffff, 0.35);
  fill.position.set(-4, 2, -3);
  scene.add(fill);
  const rimColor = new THREE.Color(theme.primary || '#6B8A72');
  const rim = new THREE.PointLight(rimColor, 0.4, 8);
  rim.position.set(-2, 1.5, -3);
  scene.add(rim);

  // rig: yaw -> tilt -> content
  const yawGroup = new THREE.Group();
  const tiltGroup = new THREE.Group();
  yawGroup.add(tiltGroup);
  scene.add(yawGroup);

  const leg = buildLeg(THREE, theme);
  tiltGroup.add(leg);

  const shadowCatcher = buildShadowCatcher(THREE);
  tiltGroup.add(shadowCatcher);

  const parts = partDefs.map((def, index) => {
    const group = new THREE.Group();
    const built = def.build(THREE);
    group.add(built);

    const base = def.mountRadius > 0 ? polar(def.angle, def.mountRadius, def.yPos) : { x: 0, y: 0, z: 0 };
    group.position.set(base.x, base.y, base.z);
    if (def.mountRadius > 0) group.rotation.y = degToRad(def.angle);

    tiltGroup.add(group);

    const materials = [];
    group.traverse((o) => {
      if (o.isMesh && o.material) materials.push(o.material);
    });

    return {
      ...def,
      index,
      group,
      basePosition: new THREE.Vector3(base.x, base.y, base.z),
      explodeDirVec: new THREE.Vector3(def.explodeDir.x, def.explodeDir.y, def.explodeDir.z).normalize(),
      materials,
      currentOpacityMul: 1,
      labelFade: 1,
      meshes: (() => {
        const arr = [];
        group.traverse((o) => {
          if (o.isMesh) arr.push(o);
        });
        return arr;
      })(),
    };
  });

  // flat lookup: mesh -> part, for raycasting
  const meshToPart = new Map();
  parts.forEach((p) => p.meshes.forEach((m) => meshToPart.set(m, p)));

  // ---- DOM overlay: labels + leader lines (created imperatively) ----
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  const lineEls = parts.map(() => {
    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    line.setAttribute('stroke', 'rgba(244,242,236,0.45)');
    line.setAttribute('stroke-width', '1');
    line.style.opacity = '0';
    svg.appendChild(line);
    return line;
  });

  const labelEls = parts.map((p) => {
    const div = document.createElement('div');
    div.className = 'kx-label';
    const strong = document.createElement('strong');
    strong.textContent = p.label;
    const span = document.createElement('span');
    span.textContent = p.desc;
    div.appendChild(strong);
    div.appendChild(span);
    labelsHost.appendChild(div);
    return div;
  });

  // ---- interaction state ----
  let isDragging = false;
  let lastX = 0;
  let lastY = 0;
  let yaw = 0.35;
  let tilt = 0.12;
  let pointerNX = 0; // normalised pointer position for parallax
  let pointerNY = 0;
  let hoveredPart = null;
  const raycaster = new THREE.Raycaster();
  const ndc = new THREE.Vector2();

  const onPointerDown = (e) => {
    isDragging = true;
    canvasHost.classList.add('kx-dragging');
    lastX = e.clientX;
    lastY = e.clientY;
    try {
      canvasHost.setPointerCapture(e.pointerId);
    } catch (err) {
      /* ignore */
    }
  };
  const onPointerMove = (e) => {
    const rect = canvasHost.getBoundingClientRect();
    pointerNX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    pointerNY = ((e.clientY - rect.top) / rect.height) * 2 - 1;

    if (isDragging) {
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      yaw += dx * 0.006;
      tilt = clamp(tilt - dy * 0.004, -0.32, 0.5);
    } else {
      ndc.set(pointerNX, -pointerNY);
      raycaster.setFromCamera(ndc, camera);
      const hits = raycaster.intersectObjects(
        parts.flatMap((p) => p.meshes),
        false
      );
      hoveredPart = hits.length ? meshToPart.get(hits[0].object) || null : null;
    }
  };
  const onPointerUp = (e) => {
    isDragging = false;
    canvasHost.classList.remove('kx-dragging');
    try {
      canvasHost.releasePointerCapture(e.pointerId);
    } catch (err) {
      /* ignore */
    }
  };
  const onPointerLeave = () => {
    hoveredPart = null;
  };

  canvasHost.addEventListener('pointerdown', onPointerDown);
  canvasHost.addEventListener('pointermove', onPointerMove);
  window.addEventListener('pointerup', onPointerUp);
  canvasHost.addEventListener('pointerleave', onPointerLeave);

  // scroll-mode detection: any real scroll cancels 'manual' toggle mode
  let lastScrollY = window.scrollY;
  const onScroll = () => {
    if (Math.abs(window.scrollY - lastScrollY) > 2) {
      modeRef.current = 'scroll';
    }
    lastScrollY = window.scrollY;
  };
  window.addEventListener('scroll', onScroll, { passive: true });

  // ---- resize ----
  function resize() {
    const rect = canvasHost.getBoundingClientRect();
    const w = Math.max(1, rect.width);
    const h = Math.max(1, rect.height);
    const pr = Math.min(window.devicePixelRatio || 1, 2);
    renderer.setPixelRatio(pr);
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  resize();
  const resizeObserver = new ResizeObserver(resize);
  resizeObserver.observe(canvasHost);

  // ---- visibility pause ----
  let isVisible = true;
  let rafId = null;

  const io = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        isVisible = entry.isIntersecting;
        if (isVisible) startLoop();
        else stopLoop();
      });
    },
    { threshold: 0 }
  );
  io.observe(spacer);

  const onVisibilityChange = () => {
    if (document.visibilityState === 'hidden') stopLoop();
    else if (isVisible) startLoop();
  };
  document.addEventListener('visibilitychange', onVisibilityChange);

  // reduced motion: static exploded state, no auto-rotate / parallax / scroll-scrub
  if (reducedMotionRef.current) {
    progressRef.current = 1;
    manualTargetRef.current = 1;
  }

  function computeScrollProgress() {
    const rect = spacer.getBoundingClientRect();
    const denom = rect.height - window.innerHeight;
    if (denom <= 0) return rect.top <= 0 ? 1 : 0;
    return clamp((0 - rect.top) / denom, 0, 1);
  }

  function frame() {
    rafId = requestAnimationFrame(frame);

    const reduced = reducedMotionRef.current;

    if (!reduced) {
      if (modeRef.current === 'scroll') {
        progressRef.current = computeScrollProgress();
      } else {
        progressRef.current = lerp(progressRef.current, manualTargetRef.current, 0.08);
      }
    }
    const progress = progressRef.current;

    // auto-rotate + parallax (skipped under reduced motion)
    if (!reduced) {
      if (!isDragging) {
        yaw += 0.0016;
        const targetParallaxYaw = pointerNX * 0.18;
        const targetParallaxTilt = -pointerNY * 0.09;
        yawGroup.rotation.y = lerp(yawGroup.rotation.y, yaw + targetParallaxYaw, 0.06);
        tiltGroup.rotation.x = lerp(tiltGroup.rotation.x, tilt + targetParallaxTilt, 0.06);
      } else {
        yawGroup.rotation.y = yaw;
        tiltGroup.rotation.x = tilt;
      }
    } else {
      yawGroup.rotation.y = yaw;
      tiltGroup.rotation.x = tilt;
    }

    leg.children.forEach((m) => {
      if (m.material) m.material.opacity = lerp(0.16, 0.06, easeOutCubic(progress));
    });

    // per-part explode + highlight
    parts.forEach((p) => {
      const local = clamp((progress - p.delay) / p.span, 0, 1);
      const eased = easeOutCubic(local);
      p.group.position.copy(p.basePosition).addScaledVector(p.explodeDirVec, eased * p.explodeDistance);

      const targetLabelFade = 1; // labels visible from the start
      p.labelFade = reduced ? targetLabelFade : lerp(p.labelFade, targetLabelFade, 0.15);

      const isHovered = hoveredPart === p;
      const anyHover = !!hoveredPart;
      const targetOpacity = anyHover ? (isHovered ? 1 : 0.32) : 1;
      p.currentOpacityMul = lerp(p.currentOpacityMul, targetOpacity, 0.15);
      p.materials.forEach((mat) => {
        const base = mat.userData.__baseOpacity ?? (mat.userData.__baseOpacity = mat.opacity);
        mat.opacity = base * p.currentOpacityMul;
      });
    });

    renderer.render(scene, camera);
    updateOverlay();
  }

  function updateOverlay() {
    const rect = canvasHost.getBoundingClientRect();
    const w = rect.width;
    const h = rect.height;
    svg.setAttribute('viewBox', `0 0 ${w} ${h}`);

    const cx = w / 2;
    const cy = h / 2;

    parts.forEach((p, i) => {
      const worldPos = p.group.getWorldPosition(new THREE.Vector3());
      const projected = worldPos.clone().project(camera);
      const sx = (projected.x * 0.5 + 0.5) * w;
      const sy = (-projected.y * 0.5 + 0.5) * h;

      // distribute label anchor points around the stage
      const angle = (i / parts.length) * Math.PI * 2;
      const labelX = clamp(cx + Math.cos(angle) * (w * 0.4), 70, w - 70);
      const labelY = clamp(cy + Math.sin(angle) * (h * 0.36), 34, h - 34);

      const line = lineEls[i];
      const label = labelEls[i];
      const fade = p.labelFade;

      line.setAttribute('x1', sx);
      line.setAttribute('y1', sy);
      line.setAttribute('x2', labelX);
      line.setAttribute('y2', labelY);
      line.style.opacity = String(fade * 0.7);

      label.style.left = `${labelX}px`;
      label.style.top = `${labelY}px`;
      label.style.opacity = String(fade);
      label.classList.toggle('kx-hovered', hoveredPart === p);
    });
  }

  function startLoop() {
    if (rafId != null) return;
    if (reducedMotionRef.current) {
      // one static render pass is enough
      renderStatic();
      return;
    }
    frame();
  }
  function stopLoop() {
    if (rafId != null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  }
  function renderStatic() {
    yawGroup.rotation.y = yaw;
    tiltGroup.rotation.x = tilt;
    parts.forEach((p) => {
      const local = clamp((1 - p.delay) / p.span, 0, 1);
      const eased = easeOutCubic(local);
      p.group.position.copy(p.basePosition).addScaledVector(p.explodeDirVec, eased * p.explodeDistance);
      p.labelFade = 1;
    });
    leg.children.forEach((m) => {
      if (m.material) m.material.opacity = 0.06;
    });
    renderer.render(scene, camera);
    updateOverlay();
  }

  startLoop();

  return function cleanup() {
    stopLoop();
    resizeObserver.disconnect();
    io.disconnect();
    document.removeEventListener('visibilitychange', onVisibilityChange);
    window.removeEventListener('scroll', onScroll);
    window.removeEventListener('pointerup', onPointerUp);
    canvasHost.removeEventListener('pointerdown', onPointerDown);
    canvasHost.removeEventListener('pointermove', onPointerMove);
    canvasHost.removeEventListener('pointerleave', onPointerLeave);

    lineEls.forEach((el) => el.remove());
    labelEls.forEach((el) => el.remove());

    scene.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
        else obj.material.dispose();
      }
    });
    renderer.dispose();
    if (renderer.domElement && renderer.domElement.parentNode) {
      renderer.domElement.parentNode.removeChild(renderer.domElement);
    }
  };
}